        ///     <see href="https://github.com/RocketWerkz/imgui/blob/v1.92.2-docking-brutal/imgui.h#L2115">imgui.h:2115</see>
        ///     <br/><c>ImGuiTableFlags_ScrollY = 1 &lt;&lt; 25</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     Scrolling
        ///   </para>
        /// </remarks>
        ScrollY = 1 << 25,

        /// <summary>
        ///   <para>
        ///     Hold shift when clicking headers to sort on multiple column. TableGetSortSpecs() may return specs where
        ///     (SpecsCount &gt; 1).
        ///   </para>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/RocketWerkz/imgui/blob/v1.92.2-docking-brutal/imgui.h#L2117">imgui.h:2117</see>
        ///     <br/><c>ImGuiTableFlags_SortMulti = 1 &lt;&lt; 26</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     Sorting
        ///   </para>
        /// </remarks>
        SortMulti = 1 << 26,

        /// <summary>
        ///   <para>
        ///     Allow no sorting, disable default sorting. TableGetSortSpecs() may return specs where (SpecsCount == 0).
        ///   </para>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/RocketWerkz/imgui/blob/v1.92.2-docking-brutal/imgui.h#L2118">imgui.h:2118</see>
        ///     <br/><c>ImGuiTableFlags_SortTristate = 1 &lt;&lt; 27</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     Sorting
        ///   </para>
        /// </remarks>
        SortTristate = 1 << 27,

        /// <summary>
        ///   <para>
        ///     Highlight column headers when hovered (may evolve into a fuller highlight)
        ///   </para>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/RocketWerkz/imgui/blob/v1.92.2-docking-brutal/imgui.h#L2120">imgui.h:2120</see>
        ///     <br/><c>ImGuiTableFlags_HighlightHoveredColumn = 1 &lt;&lt; 28</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     Miscellaneous
        ///   </para>
        /// </remarks>
        HighlightHoveredColumn = 1 << 28,

        /// <summary>
        ///   <para>
        ///     C++:
        ///     <see href="https://github.com/RocketWerkz/imgui/blob/v1.92.2-docking-brutal/imgui.h#L2123">imgui.h:2123</see>
        ///     <br/>
        ///     <c>ImGuiTableFlags_SizingMask_ = ImGuiTableFlags_SizingFixedFit | ImGuiTableFlags_SizingFixedSame | ImGuiTableFlags_SizingStretchProp | ImGuiTableFlags_SizingStretchSame</c>
        ///   </para>
        /// </summary>
        /// <remarks>
        ///   <para>
        ///     [Internal] Combinations and masks
        ///   </para>
        /// </remarks>
        SizingMask = SizingFixedFit | SizingFixedSame | SizingStretchProp | SizingStretchSame,
    }
}
